import { Group, Mesh, PlaneGeometry, CylinderGeometry, TorusKnotGeometry, DirectionalLight, AmbientLight, MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, mix, smoothstep, length, sub, add, mul, div, time, uniform } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const group = new Group();

  // ---------- Backdrop ----------
  const backdropGeom = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({ transparent: true });
  const vUvBackdrop = uv();
  const grad0 = vec3(0.043, 0.043, 0.0627); // #0b0b10
  const grad1 = vec3(0.063, 0.063, 0.0902); // #101017
  const grad2 = vec3(0.087, 0.087, 0.114);  // #16161d
  const tBack = vUvBackdrop.y;
  const colBackStep1 = mix(grad0, grad1, smoothstep(0.0, 0.7, tBack));
  const colBack = mix(colBackStep1, grad2, smoothstep(0.7, 1.0, tBack));
  backdropMat.colorNode = colBack;
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.z = -3;
  group.add(backdrop);

  // ---------- Pedestal ----------
  const pedGeom = new CylinderGeometry(1.1, 1.1, 0.5, 32);
  const pedMat = new MeshStandardNodeMaterial({
    color: 0x14141a,
    roughness: 0.7,
    metalness: 0.35,
  });
  const pedestal = new Mesh(pedGeom, pedMat);
  // top face at y = -0.35 => center y = -0.35 - height/2
  pedestal.position.y = -0.35 - 0.25;
  group.add(pedestal);

  // ---------- Contact Shadow ----------
  const shadowGeom = new PlaneGeometry(3, 3);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const vUvShadow = uv();
  const centerUv = vec2(0.5, 0.5);
  const dist = length(sub(vUvShadow, centerUv));
  const opacity = smoothstep(0.0, 0.4, sub(0.4, dist));
  shadowMat.opacityNode = opacity;
  shadowMat.colorNode = vec3(0, 0, 0);
  const shadow = new Mesh(shadowGeom, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = -0.36;
  group.add(shadow);

  // ---------- Torus Knot ----------
  const knotGeom = new TorusKnotGeometry(0.7, 0.22, 220, 36);
  const knotMat = new MeshStandardNodeMaterial({
    metalness: 0.55,
    roughness: 0.55,
    clearcoat: 0.22,
    clearcoatRoughness: 0.35,
    anisotropy: 0.9,
  });
  const knot = new Mesh(knotGeom, knotMat);
  knot.position.y = 0.4;
  group.add(knot);

  // Load brushed‑metal map for roughness
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texturePromise.then((tex) => {
    knotMat.roughnessMap = tex;
    knotMat.needsUpdate = true;
  });

  // ---------- Text ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const opts = {
      fontSize: item.typography?.fontSize ?? 68,
      color: item.role === 'headline' ? '#16161d' : '#e8ecf2',
      align: 'center',
    };
    const txt = ctx.fontAtlas.createText(item.text, opts);
    txt.position.y = item.role === 'headline' ? -1.2 : -1.6;
    group.add(txt);
  }

  // ---------- Lights ----------
  const ambient = new AmbientLight(0xffffff, 0.6);
  group.add(ambient);
  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2, 2, 2);
  group.add(keyLight);
  const rimLight = new DirectionalLight(0xffffff, 0.8);
  rimLight.position.set(-2, -2, -2);
  group.add(rimLight);

  // ---------- Cinematic Primitive ----------
  const orbit = ctx.primitives['orbit'](group, { speed: 0.1, radius: 0.4 });

  // ---------- Cleanup ----------
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    // Dispose textures
    texturePromise.then((tex) => tex.dispose()).catch(() => {});
    // Dispose materials
    backdropMat.dispose();
    pedMat.dispose();
    shadowMat.dispose();
    knotMat.dispose();
    // Cleanup primitive
    if (orbit && orbit.cleanup) orbit.cleanup();
    // Kill any GSAP tweens attached to this group
    gsap.killTweensOf(group);
  };

  return group;
}
